{
  "query": "query Slots($filter: AvailabilityFilterInput) { availableSlots(filter: $filter) { advisor { id name } visaType start end } }",
  "variables": {
    "filter": {
      // No filter: this returns every bookable slot.
      // The next four requests show the filters you can add here.
    }
  }
}

{
  "query": "query Slots($filter: AvailabilityFilterInput) { availableSlots(filter: $filter) { advisor { id name } visaType start end } }",
  "variables": {
    "filter": {
      // Which visa type? Change the value and press Send.
      //   "A" = Skilled Worker, 30 minute appointment
      //   "B" = Family / Dependent, 60 minute appointment
      "visaType": "A"
    }
  }
}

{
  "query": "query Slots($filter: AvailabilityFilterInput) { availableSlots(filter: $filter) { advisor { id name } visaType start end } }",
  "variables": {
    "filter": {
      // Which advisor? Change the value and press Send.
      //   "ia-001" = Sofia Andersson
      //   "ia-002" = Rajan Patel
      // Worth a look: Rajan on 10 March has slots at 09:00 and then 09:33. He has two
      // separate windows that morning, and they are not joined into one.
      "advisorId": "ia-002"
    }
  }
}

{
  "query": "query Slots($filter: AvailabilityFilterInput) { availableSlots(filter: $filter) { advisor { id name } visaType start end } }",
  "variables": {
    "filter": {
      // Which day or period? Change the dates and press Send.
      // Times are UTC, written like 2025-03-10T00:00:00Z.
      // The seed data covers 10 March to 21 March 2025.
      // "from" and "to" can be used together or on their own.
      "from": "2025-03-10T00:00:00Z",
      "to": "2025-03-11T00:00:00Z"
    }
  }
}

{
  "query": "query Slots($filter: AvailabilityFilterInput) { availableSlots(filter: $filter) { advisor { id name } visaType start end } }",
  "variables": {
    "filter": {
      // Change any of these and press Send.
      //   visaType:   "A" = Skilled Worker (30 minutes), "B" = Family / Dependent (60 minutes)
      //   advisorId:  "ia-001" = Sofia Andersson, "ia-002" = Rajan Patel
      //   from / to:  UTC times like 2025-03-10T00:00:00Z. The seed data covers 10 to 21 March 2025.
      // To drop a filter, delete its line (the last line must not end with a comma).
      // Worth a look: Sofia on 11 March returns nothing. Her window that day is
      // 20 minutes, too short for any appointment.
      "visaType": "A",
      "advisorId": "ia-001",
      "from": "2025-03-11T00:00:00Z",
      "to": "2025-03-12T00:00:00Z"
    }
  }
}

{
  "query": "mutation RequestBooking($input: RequestBookingInput!) { requestBooking(input: $input) { id candidateName visaType status start end createdAt expiresAt advisor { id name } } }",
  "variables": {
    "input": {
      // Who is booking? Any name. A candidate can have one active request at a time,
      // so use a name that has no booking or waitlist place already.
      "candidateName": "Amina Yusuf",
      // Which visa type? It decides how long the appointment is.
      //   "A" = Skilled Worker, 30 minute appointment
      //   "B" = Family / Dependent, 60 minute appointment
      "visaType": "B"
      // With only a name and visa type, the earliest free slot is assigned.
      // To ask for a particular advisor or time, add either or both of these lines
      // (and a comma after the line above):
      //   "advisorId": "ia-001",
      //   "slotStart": "2025-03-12T10:00:00Z"
    }
  }
}

{
  "query": "query Slots($filter: AvailabilityFilterInput) { availableSlots(filter: $filter) { advisor { id name } visaType start end } }",
  "variables": {
    "filter": {
      // Filled in from step 2.1: that booking's advisor and day.
      // You can type your own values instead.
      "advisorId": "{{bookingAdvisorId}}",
      "from": "{{bookingDayFrom}}",
      "to": "{{bookingDayTo}}"
    }
  }
}

{
  "query": "mutation ConfirmBooking($input: ConfirmBookingInput!) { confirmBooking(input: $input) { id status confirmedAt } }",
  "variables": {
    "input": {
      // Filled in from step 2.1: the booking and the advisor it was assigned to.
      // Only the assigned advisor can confirm. Try the other advisor id to see it refused.
      //   "ia-001" = Sofia Andersson
      //   "ia-002" = Rajan Patel
      "bookingId": "{{bookingId}}",
      "advisorId": "{{bookingAdvisorId}}"
    }
  }
}

